RESULTS_EXPERIMENT = RESULTS_PUBLISHED / "experiment"

#: Per-seed output for the one-step active inference agent.
RESULTS_SI_RAW = RESULTS_SI / "data"


def rel(path) -> str:
    """Format a path for display, relative to the repository root.

    Printed paths end up in committed notebook outputs, so they must not carry the
    home directory of whoever happened to run the cell. Falls back to the bare name
    for anything outside the repository, such as an interpreter in a global env.
    """
    p = Path(path)
    try:
        return str(p.relative_to(REPO_ROOT))
    except ValueError:
        return p.name


def results_dpefe_raw(planning_horizon: int) -> Path:
    """Per-seed output for the DPEFE agent at a given planning horizon (2, 5, 10, 20)."""
    return RESULTS_DPEFE / f"M{planning_horizon}"


