# --- private data ------------------------------------------------------------

#: In-vitro culture recordings. Not redistributable, and excluded from version
#: control. Code that reads this must fail with a clear message when it is absent.
PRIVATE_DATA = REPO_ROOT / "data" / "private"
IN_VITRO_CSV = PRIVATE_DATA / "in_vitro_cells_sentience.csv"


def require_in_vitro() -> Path:
    """Return the in-vitro CSV path, or explain why it is missing.

    The recordings are not public, so a clone of this repository cannot reproduce
    the analyses that depend on them. Failing here with an explanation beats a bare
    FileNotFoundError three frames deep in pandas.
    """
    if not IN_VITRO_CSV.exists():
        raise FileNotFoundError(
            f"{IN_VITRO_CSV} not found.\n"
            "The in-vitro culture recordings are not distributed with this repository. "
            "Analyses that compare against the biological data cannot be run without them; "
            "see REPRODUCE.md for which results this affects."
        )
    return IN_VITRO_CSV
